"""Detect and preserve mandatory notes generated by the knowledge-graph agent."""

import ast
import json
import re
from collections.abc import Iterable

CODE_FENCE_PATTERN = re.compile(r"```.*?```", re.DOTALL)
SENTENCE_BOUNDARY_PATTERN = re.compile(r"(?<=[.!?])\s+")
STRING_LITERAL_PATTERN = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', re.DOTALL)
PROVENANCE_PATTERN = re.compile(
    r"(?:^|\s)(?:provenance(?:\s*note)?|procedencia(?:\s+declarada)?|fuente|source|origen|informe)\s*:",
    re.IGNORECASE,
)
NOTE_LABEL_PATTERN = re.compile(
    r"^\s*(?:texto\s+generado|generated\s+text|provenance(?:\s*note)?|"
    r"procedencia(?:\s+declarada)?|fuente|source|origen|informe)\s*:\s*",
    re.IGNORECASE,
)
ROOT_CARD_PATTERN = re.compile(r"\broot\s*=\s*Card\s*\(")
QUOTE_PAIRS = {'"': '"', "'": "'", "«": "»"}
DISCLAIMER_TRIGGERS = (
    "interpretación generada por un modelo de lenguaje",
    "interpretation generated by a language model",
    "no es un dato de la fecha",
    "hecho verificado",
    "not a verified fact",
)
IN_SAMPLE_TRIGGERS = (
    "in-sample",
    "in sample",
    "en muestra",
    "dentro de muestra",
)


def _normalize_note(note: str) -> str:
    return " ".join(note.split())


def _strip_outer_quotes(text: str) -> str:
    stripped = text.strip()
    if not stripped:
        return stripped
    closer = QUOTE_PAIRS.get(stripped[0])
    if closer is None:
        return stripped
    end = len(stripped)
    while end > 1 and (stripped[end - 1] in ".,;:" or stripped[end - 1].isspace()):
        end -= 1
    if end > 1 and stripped[end - 1] == closer:
        return stripped[1 : end - 1].strip()
    return stripped


def _core_note(note: str) -> str:
    core = _normalize_note(note)
    for _ in range(2):
        core = NOTE_LABEL_PATTERN.sub("", core, count=1).strip()
        core = _strip_outer_quotes(core)
    return core.rstrip(".,;:")


def _split_inline_provenance(line: str) -> tuple[list[str], str]:
    matches = list(PROVENANCE_PATTERN.finditer(line))
    if not matches:
        return [], line

    clauses: list[str] = []
    segments: list[str] = []
    cursor = 0
    for index, match in enumerate(matches):
        start = match.start()
        while start > 0 and line[start - 1].isspace():
            start -= 1
        end = matches[index + 1].start() if index + 1 < len(matches) else len(line)
        while end > start and line[end - 1].isspace():
            end -= 1
        clauses.append(line[match.start() : end].strip())
        segments.append(line[cursor:start])
        cursor = end
    segments.append(line[cursor:])
    return clauses, " ".join(segment.strip() for segment in segments if segment.strip())


def merge_notes(notes: Iterable[str]) -> tuple[str, ...]:
    """Deduplicate notes while preserving their first-seen order."""
    merged: list[str] = []
    seen: set[str] = set()
    for note in notes:
        normalized = _normalize_note(note)
        if normalized and normalized not in seen:
            seen.add(normalized)
            merged.append(normalized)
    return tuple(merged)


def _contains_any(text: str, triggers: tuple[str, ...]) -> bool:
    folded = text.casefold()
    return any(trigger in folded for trigger in triggers)


def extract_mandatory_notes(text: str) -> tuple[str, ...]:
    """Extract verbatim generated-text, in-sample and provenance notes."""
    cleaned = CODE_FENCE_PATTERN.sub("\n", text)
    notes: list[str] = []

    for block in re.split(r"\n\s*\n", cleaned):
        block = block.strip()
        if not block:
            continue
        body_parts: list[str] = []
        for line in block.splitlines():
            clauses, remainder = _split_inline_provenance(line)
            notes.extend(clauses)
            if remainder.strip():
                body_parts.append(remainder.strip())
        body = " ".join(body_parts).strip()
        body = NOTE_LABEL_PATTERN.sub("", body, count=1).strip()
        body = _strip_outer_quotes(body)
        if not body:
            continue
        sentences = [part.strip() for part in SENTENCE_BOUNDARY_PATTERN.split(body) if part.strip()]
        for index, sentence in enumerate(sentences):
            if _contains_any(sentence, DISCLAIMER_TRIGGERS):
                notes.append(" ".join(sentences[index:]))
                break
            if _contains_any(sentence, IN_SAMPLE_TRIGGERS):
                notes.append(sentence)

    return merge_notes(notes)


def _decode_literal(raw: str) -> str:
    try:
        value = json.loads(raw) if raw.startswith('"') else ast.literal_eval(raw)
    except (SyntaxError, ValueError):
        return raw[1:-1]
    return value if isinstance(value, str) else raw[1:-1]


def _literal_text(openui_lang: str) -> str:
    values = [
        _decode_literal(match.group(0)) for match in STRING_LITERAL_PATTERN.finditer(openui_lang)
    ]
    return _normalize_note(" ".join(values))


def _plain_text(text: str) -> str:
    return _normalize_note(re.sub(r"[*_`]+", "", text))


def _note_sentences(note: str) -> list[str]:
    return [
        sentence.strip() for sentence in SENTENCE_BOUNDARY_PATTERN.split(note) if sentence.strip()
    ]


def _note_present(openui_lang: str, note: str) -> bool:
    normalized = _normalize_note(note)
    literal_text = _literal_text(openui_lang).casefold()
    plain_text = _plain_text(literal_text).casefold()
    haystacks = (literal_text, plain_text)

    folded = normalized.casefold()
    if any(folded in text for text in haystacks):
        return True

    core = _plain_text(_core_note(normalized)).casefold()
    if core and any(core in text for text in haystacks):
        return True

    sentences = _note_sentences(normalized)
    cores = [_plain_text(_core_note(sentence)).casefold() for sentence in sentences]
    return bool(cores) and all(
        bool(sentence) and any(sentence in text for text in haystacks) for sentence in cores
    )


def _matching_bracket(text: str, start: int) -> int:
    depth = 0
    quote: str | None = None
    escaped = False
    for index in range(start, len(text)):
        character = text[index]
        if quote is not None:
            if escaped:
                escaped = False
            elif character == "\\":
                escaped = True
            elif character == quote:
                quote = None
            continue
        if character in {'"', "'"}:
            quote = character
        elif character == "[":
            depth += 1
        elif character == "]":
            depth -= 1
            if depth == 0:
                return index
    return -1


def _root_card_bounds(text: str) -> tuple[int, int] | None:
    match = ROOT_CARD_PATTERN.search(text)
    if match is None:
        return None
    opening = text.find("[", match.end())
    if opening == -1:
        return None
    closing = _matching_bracket(text, opening)
    if closing == -1:
        return None
    return opening, closing


def append_missing_notes(openui_lang: str, notes: Iterable[str]) -> str:
    """Append any missing note as a small TextContent and reference it from root."""
    mandatory = merge_notes(notes)
    missing = [note for note in mandatory if not _note_present(openui_lang, note)]
    if not missing:
        return openui_lang
    bounds = _root_card_bounds(openui_lang)
    if bounds is None:
        return openui_lang

    opening, closing = bounds
    existing_names = set(re.findall(r"\bmandatoryNote\d+\b", openui_lang))
    statements: list[str] = []
    references: list[str] = []
    next_index = 1
    for note in missing:
        while f"mandatoryNote{next_index}" in existing_names:
            next_index += 1
        name = f"mandatoryNote{next_index}"
        existing_names.add(name)
        references.append(name)
        statements.append(f'{name} = TextContent({json.dumps(note, ensure_ascii=False)}, "small")')
        next_index += 1

    inner = openui_lang[opening + 1 : closing]
    if inner.strip():
        separator = "" if inner.rstrip().endswith(",") else ","
        addition = f"{separator} {', '.join(references)}"
    else:
        addition = ", ".join(references)
    updated = f"{openui_lang[:closing]}{addition}{openui_lang[closing:]}"
    return f"{updated.rstrip()}\n" + "\n".join(statements)


def preserve_mandatory_notes(openui_lang: str, source_text: str) -> str:
    """Extract mandatory notes from source text and append missing ones."""
    return append_missing_notes(openui_lang, extract_mandatory_notes(source_text))
